"""Exception definitions."""

from jsilib import _utils, exc

__all__ = export = _utils.ExportList()


@export
class TransportError(exc.JSILIBError):
    """Base class for transport layer errors."""


@export
class ConnectionClosedError(exc.JSILIBError):
    """Raised when frame is being read from or written to a closed
    transport connection."""


@export
class AcceptorClosedError(TransportError):
    """Raised by :class:`ITransportAcceptor.accept` when it is called on a
    closed acceptor or when acceptor was closed while awaiting for a new
    connection."""


@export
class FrameDecodeError(TransportError):
    """Raised when it was not possible to properly decode incoming frame."""
    __message_template__ = "{self.message}"

    def __init__(self, message: str):
        super().__init__()
        self._message = message

    @property
    def message(self) -> str:
        return self._message
